("DBD1E28A52", 0, "Đoạn về thu hút trẻ tham gia hoạt động (cho lựa chọn, ngồi đối diện), không về xử trí hành vi thách thức.", "", "medium"),
("56917C6376", 0, "Đoạn là tài liệu tham khảo và phương pháp đào tạo người hướng dẫn, không có hướng dẫn xử trí hành vi.", "", "high"),
("E2C9E25A4F", 0, "Đoạn về kết quả phân tích gộp chức năng thích ứng, không về xử trí hành vi thách thức.", "", "high"),
("B120A7E25E", 0, "Bảng đặc điểm các chương trình nuôi dạy con, không liên quan.", "", "high"),
("667CF1FEF8", 2, "Câu hỏi tự kiểm tra ghép hành vi thách thức với mục tiêu phản ứng (không cho đồ khi có hành vi, phớt lờ rồi khen, đặt kỳ vọng rõ ràng); hỗ trợ trả lời.", "Give no attention or response (ignore the behaviour) then reward appropriate behaviour with praise and attention.", "high"),
("9A5627CC3F", 3, "Đoạn nêu nhiệt kế hành vi, lịch trình hình ảnh và bốn mục tiêu phản ứng với hành vi thách thức theo lý do; trực tiếp và cụ thể.", "Four goals for responding to challenging behaviour", "high"),
("E711D0D693", 1, "Tóm tắt nghiên cứu cho thấy can thiệp nuôi dạy con ở dân số chung giảm vấn đề hành vi; không có hướng dẫn cụ thể.", "We found that parenting interventions improved early child cognitive, language, motor, socioemotional development, and attachment and reduced behavior problems.", "medium"),
("266BFADD7F", 0, "Đoạn về phân tích yếu tố điều chỉnh hiệu quả can thiệp nuôi dạy con, không về hành vi thách thức.", "", "high"),
("918E9B8B0C", 1, "Đoạn giải thích trẻ có thể dùng hành vi thách thức để giao tiếp và cha mẹ cần quan sát; chỉ là bối cảnh để hiểu hành vi.", "Children may use challenging behaviour to communicate when other ways of communicating are difficult.", "medium"),
("84EB850DBA", 2, "Danh sách câu hỏi giúp cha mẹ phân tích hành vi (điều gì xảy ra trước/sau, lý do, cách phòng và phản ứng); hỗ trợ trả lời.", "What could you do to prevent the behaviour? How should you respond based on the reason for the behaviour?", "medium"),
("C7923CDB54", 0, "Bảng đặc điểm các chương trình nuôi dạy con, không liên quan.", "", "high"),
("E8B3D63578", 0, "Đoạn về tác động của can thiệp lên cha mẹ (trầm cảm, sự tham gia của cha), không về xử trí hành vi thách thức.", "", "high"),
("BAC82CEB61", 3, "Đoạn đáp án giải thích cụ thể cách xử trí từng tình huống hành vi thách thức ở nhà: thẻ first-then, đếm ngược, không cho thêm thời gian, phớt lờ rồi khen khi trẻ im lặng.", "It would be best if he did not look at Anna or talk to her while she is showing challenging behaviour. Then as soon as she is quiet, he should go to her and tell her that she is doing a good job being quiet.", "high"),
("54586E9C4C", 0, "Bảng đặc điểm các chương trình nuôi dạy con, không liên quan.", "", "high"),
("C8A6A70B74", 3, "Đoạn hướng dẫn cách phản ứng với hành vi thách thức nhằm tìm cảm giác: thay bằng hành vi an toàn tạo cùng cảm giác và dạy trẻ cách xin.", "Teach a safe and appropriate behaviour to replace sensation-seeking challenging behaviour.", "high"),
